parts.append('</select></label><span id="count" aria-live="polite">107 requirements</span></div><div class="table-wrap"><table id="requirements"><thead><tr><th>ID / pack</th><th>Original requirement</th><th>Native status and missing work</th><th>Preview / evidence</th></tr></thead><tbody>')
for r in a['rows']:
 parts.append('<tr data-status="'+r['native_status']+'" data-pack="'+e(r['pack'])+'"><td>'+e(r['id'])+'<div class="small">'+e(r['pack'])+'</div></td><td class="requirement">'+e(r['requirement'])+'</td><td class="evidence"><b class="status">'+labels[r['native_status']]+'</b>'+e(r['gap'])+'</td><td class="evidence">'+e(r['preview'])+('<p class="small">Local evidence: '+e('; '.join(r['evidence']))+'</p>' if r['evidence'] else '')+'</td></tr>')
parts.append('</tbody></table></div><h2>Acceptance checks T1–T12 / A1–A12</h2><p>Current browser tests are additional checks; they are not replacements for these acceptance tests.</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Required check</th><th>State / evidence</th></tr></thead><tbody>')
for r in a['acceptance']:parts.append('<tr><td>'+e(r['id'])+'</td><td>'+e(r['requirement'])+'</td><td>'+e(r['status'])+' — '+e(r['evidence'])+'</td></tr>')
parts.append('</tbody></table></div><h2>Scope changes and unresolved deviations</h2><ul>')
for kind,text in a['changes']:parts.append('<li><b>'+e(kind)+':</b> '+e(text)+'</li>')
