for text in a['priorities']:parts.append('<li>'+e(text)+'</li>')
parts.append('</ol><details><summary>20 realism work areas mapped back to the PRD</summary><ol>')
for _,title,ids in a['realism']:parts.append('<li>'+e(title)+' <span class="small">'+e(ids)+'</span></li>')
parts.append('</ol></details><details><summary>Inspection evidence and limits</summary><p>Six Python files parse; five existing Bash scripts pass bash -n. Representative CLI help/version/unknown-input exits were checked. shellcheck is unavailable. Generator, pack targets/appliers, native widgets/daemon, package definitions and native LICENSE are missing. No native install was run.</p><p>GitHub metadata for the supplied repository resolves to <code>'+e(a['repository']['resolved'])+'</code> and reports size 0. This session has pushed the private Site source, not the native kit into that repository.</p><p>Live browser visual QA and target desktop/VM tests have not run. The required Design Spec was not supplied; original palette colours remain provisional.</p></details><p class="footer">This is a coverage snapshot, not a declaration of v1 completion. Update statuses only with linked native evidence and acceptance results.</p></main><script>const q=document.getElementById("query"),s=document.getElementById("status"),p=document.getElementById("pack"),rows=[...document.querySelectorAll("#requirements tbody tr")];function filter(){let n=0;for(const row of rows){const show=(!s.value||row.dataset.status===s.value)&&(!p.value||row.dataset.pack===p.value)&&row.textContent.toLowerCase().includes(q.value.toLowerCase());row.hidden=!show;if(show)n++;}document.getElementById("count").textContent=n+" requirements";}q.oninput=s.onchange=p.onchange=filter;</script></body></html>')
(root/'dist/prd-status.html').write_text(''.join(parts))
(root/'dist/prd-coverage.json').write_text(json.dumps(a,indent=2)+'\n')
